// reproduce.js
// This script launches Chrome with the LastPass extension loaded, runs Lighthouse
// against example.com, and prints out the two relevant audits so you can see
// that bfcache fails even though no‐unload‐listeners passes.
import lighthouse from 'lighthouse';
import {launch as launchChrome} from 'chrome-launcher';

async function run() {
  // TODO: update this to the path where you have unpacked the LastPass extension.
  // You can download the CRX from the Web Store and unzip it, or clone from
'the LastPass GitHub mirror. The path below is just an example.
  const extensionPath = '/full/path/to/unpacked/lastpass/extension';

  // Launch Chrome with the extension loaded
  const chrome = await launchChrome({
    chromeFlags: [
      `--disable-extensions-except=${extensionPath}`,
      `--load-extension=${extensionPath}`,
    ],
  });

  // Run Lighthouse against https://example.com on the port returned by chrome-launcher
  const flags = {
    port: chrome.port,
    output: 'json',
  };

  const { lhr } = await lighthouse('https://example.com', flags);

  // Print out the two audits of interest
  console.log('--- bfcache audit ---');
  console.log(`score: ${lhr.audits['bfcache'].scoreDisplayMode === 'binary' ? lhr.audits['bfcache'].score : 'n/a'}`);
  console.log(`explanation: ${lhr.audits['bfcache'].explanation}`);

  console.log('\n--- no-unload-listeners audit ---');
  console.log(`score: ${lhr.audits['no-unload-listeners'].scoreDisplayMode === 'binary' ? lhr.audits['no-unload-listeners'].score : 'n/a'}`);
  console.log(`displayValue: ${lhr.audits['no-unload-listeners'].displayValue}`);

  await chrome.kill();
}

run().catch(err => {
  console.error(err);
  process.exit(1);
});
